def transform(grid):
    R, C = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    line_colors = set(v for row in grid for v in row) - {bg, 4}

    def scan(r, c, dr, dc):
        # walk until first non-bg cell or edge; True if line color found
        rr, cc = r + dr, c + dc
        while 0 <= rr < R and 0 <= cc < C:
            v = grid[rr][cc]
            if v != bg:
                return v in line_colors
            rr += dr
            cc += dc
        return False

    out = [row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c] != bg:
                continue
            up = scan(r, c, -1, 0)
            down = scan(r, c, 1, 0)
            horiz = scan(r, c, 0, -1) or scan(r, c, 0, 1)
            if up and down and horiz:
                out[r][c] = 4
    return out
